mapper.select:
select c.*, e.name 'masterName', case when c.begin_date > CURDATE() then '未开班' when c.end_date < CURDATE() then '已结课' else '在读' end 'status' from clazz c left join emp e on c.master_id = e.id
c.name like CONCAT('%', #{name}, '%')
and c.begin_date <= #{begin}
and c.end_date >= #{end}
order by c.update_time desc
